from urllib.parse import quote, quote_plus, unquote, urlsplit

from .contracts import FIELDS, load_bundle, record_digest, require, validate_bundle

BINARY_SHA = "631de1401390e53ecccf643586879097e23b363a7afea56374e95188f63def78"
TOOLS_SHA = "387088e0c7c508bb2521a48635757887852f9f9a7fa3ff7c5d8844760325d76b"
CONTAINER = "845fa540c621ab48bba9d736718259fefc78e4a7888d67696d95444a1b5587af"
ROOT = Path(__file__).resolve().parents[2]
SANDBOX = ROOT / "integrations/brain/qualification/sandbox"
BASE = "/qualification/sandbox"
MAX_NATIVE_FRAME_BYTES = 16 * 1024 * 1024  # Local capture limit, not a native server limit.


def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False)

def _json_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("duplicate JSON member")
        result[key] = value
    return result


def _json_constant(value):
    raise ValueError("nonfinite JSON constant")


def _json_float(value):
    number = float(value)
    if not math.isfinite(number):
        raise ValueError("nonfinite JSON number")
    return number


def _strict_json(value):
    """Do not erase duplicate members, nonfinite values or unsupported encoding."""
    if type(value) is bytes:
        value = value.decode("utf-8", errors="strict")
    if type(value) is not str:
        raise TypeError("JSON text required")
    return json.loads(value, object_pairs_hook=_json_object,
                      parse_constant=_json_constant, parse_float=_json_float)


def safe_native_error(body, secrets=()):
    """Admit exactly one bounded causal envelope; any extra node is incomplete."""
    withheld = {"code": None, "message": None, "complete": False}
    node = body
    if type(node) is dict:
        if set(node) == {"error"}:
            node = node["error"]
        elif "content" in node:
            if not set(node) <= {"content", "isError"} or ("isError" in node and node["isError"] is not True):
                return withheld
            content = node["content"]
            if type(content) is not list or len(content) != 1:
                return withheld
            leaf = content[0]
            if type(leaf) is not dict or set(leaf) != {"type", "text"} or leaf["type"] != "text":
                return withheld
            node = leaf["text"]
        elif "structuredContent" in node:
            if not set(node) <= {"structuredContent", "isError"} or ("isError" in node and node["isError"] is not True):
                return withheld
            node = node["structuredContent"]
    if type(node) is str:
        if len(node) > 8192:
            return withheld
        for prefix in ("brain_remember failed: ", "brain_get failed: "):
            if node.startswith(prefix):
                node = node[len(prefix):]
                break
        if node.startswith("{"):
            try:
                node = _strict_json(node)
            except BaseException:
                return withheld
            if type(node) is dict and set(node) == {"error"}:
                node = node["error"]
    code = None
    if type(node) is dict:
        if "message" not in node or not set(node) <= {"code", "message"}:
            return withheld
        code = node.get("code")
        if "code" in node:
            allowed = (type(code) is str and code in {"IDEMPOTENCY_CONFLICT", "UNAUTHORIZED", "NOT_FOUND", "54000", "22023", "23505"}) or (type(code) is int and code in {-32700, -32600, -32601, -32602, -32603, -32000})
            if not allowed:
                return withheld
        node = node["message"]
    if type(node) is not str or len(node) > 512 or any(secret and secret in node for secret in secrets):
        return {"code": code, "message": None, "complete": False}
    for prefix in ("error returned from database: ", "database error: ", "ERROR: "):
        if node.startswith(prefix):
            node = node[len(prefix):]
    patterns = (r"string is too long for tsvector \(([0-9]{1,19}) bytes, max ([0-9]{1,19}) bytes\)",
                r"index row requires ([0-9]{1,19}) bytes, maximum size is ([0-9]{1,19})",
                r"value too long for type character varying\(([0-9]{1,19})\)")
    for pattern in patterns:
        match = re.fullmatch(pattern, node)
        if match and all(0 <= int(value) <= 9223372036854775807 for value in match.groups()):
            return {"code": code, "message": node, "complete": True}
    return {"code": code, "message": None, "complete": False}


def native_identity(result, brain_id):
    """Reject oversized/foreign identities before output or a conditional get."""
    if not isinstance(result, dict):
        return None
    memory_id, revision = result.get("memory_id"), result.get("revision")
    if result.get("brain_id") != brain_id or not isinstance(memory_id, str) or re.fullmatch(r"[1-9][0-9]{0,18}", memory_id) is None:
        return None
    if int(memory_id) > 9223372036854775807 or type(revision) is not int or not 1 <= revision <= 9223372036854775807:
        return None
    action = result.get("action")
    if action is not None and (not isinstance(action, str) or re.fullmatch(r"[a-z][a-z0-9_-]{0,79}", action) is None):
        return None
    identity = {"brain_id": result["brain_id"], "memory_id": memory_id, "revision": revision}
    if action is not None:
        identity["action"] = action
    return identity


class NativeError(RuntimeError):
    def __init__(self, body):
        self.body = body
        super().__init__("Native Brain rejected call: " + record_digest(body))


def isolated_argv(*, denied=False):
    """Use only the parent-admitted stopped-runtime identity; never start it here."""
    info = _strict_json(subprocess.check_output(["docker", "inspect", CONTAINER], stderr=subprocess.DEVNULL, timeout=5))[0]
    require(info["Id"] == CONTAINER and info["State"]["Running"], "admitted runtime not running")
    require(info["Config"]["User"] == "1001:1001", "native OS principal drift")
    host = info["HostConfig"]
    require(host["NetworkMode"] == "none" and host["ReadonlyRootfs"] and not host["PortBindings"]
            and not host["Privileged"], "native isolation drift")
    require(info["Image"] == "sha256:cf134a767f474095eeba57e0117be8e568e011a63f33fbf252f14c9b760f8e6f", "native image drift")
    mounts = {m["Destination"]: m for m in info["Mounts"]}
    expected = {"/opt/brain": (Path("/home/genie/.brain/bin"), False), BASE: (SANDBOX, True),
                "/licensed-sources": (ROOT / "investigations/frontier-economics/licensed-sources", False),
                "/var/lib/postgresql/data": (SANDBOX / "pgdata", True)}
    require(len(info["Mounts"]) == len(expected) and set(mounts) == set(expected), "native mounts drift")
    for dest, (source, writable) in expected.items():
        require(mounts[dest]["Type"] == "bind" and Path(mounts[dest]["Source"]).resolve() == source.resolve()
                and mounts[dest]["RW"] == writable, "native bind drift")
    require(hashlib.sha256(Path("/home/genie/.brain/bin/brain").read_bytes()).hexdigest() == BINARY_SHA, "native binary drift")
    role = "oi5_denied" if denied else "oi5_owner"
    password = (SANDBOX / ("denied-password" if denied else "owner-password")).read_text().strip()
    dsn = f"postgresql://{role}:{password}@127.0.0.1:5432/brain"
    env = {"PATH": "/opt/brain:/usr/bin:/bin", "HOME": BASE + "/home", "BRAIN_HOME": BASE + "/home/.brain",
           "XDG_RUNTIME_DIR": BASE + "/socket", "TMPDIR": BASE + "/tmp", "DATABASE_URL": dsn,
           "BRAIN_CONTROL_DATABASE": "brain", "BRAIN_MEMORY_VECTORS": "off", "BRAIN_OMNI_GLOBAL_KILL": "1",
           "BRAIN_QUIET": "1", "BRAIN_ID": "brn_63n8pr"}
    return ["docker", "exec", "-i", "-u", "1001:1001", "-w", BASE + "/vault", CONTAINER,
            "env", "-i", *(f"{k}={v}" for k, v in env.items()), "/opt/brain/brain-mcp"]


class NativeTransportError(RuntimeError):
    def __init__(self, phase, receipt):
        self.receipt = receipt
        super().__init__("Native transport failed: " + phase)


class BrainEvidence:
    def __init__(self, argv, *, brain_id, witness=None):
        require(re.fullmatch(r"brn_[a-z0-9_]{1,72}", brain_id) is not None, "explicit Brain authority required")
        self.brain_id, self.sequence, self.calls, self.requests = brain_id, 0, [], []
        self.witness, self.last_request, self.redactions = witness, None, ()
        for arg in argv:
            if arg.startswith("DATABASE_URL="):
                password = urlsplit(arg[len("DATABASE_URL="):]).password
                if password:
                    password = unquote(password)
                    self.redactions = (password, quote(password, safe=""), quote_plus(password))
        self.pending, self.receive_failed = queue.Queue(maxsize=2), None
        self.reader_end_kind = None
        # The existing optional observer may carry the ONE private immutable
        # host-monotonic cutoff. Ordinary production observers/defaultNone do not.
        self._native_admission_deadline = getattr(witness, "_native_admission_deadline", None)
        require(self._native_admission_deadline is None or
                (type(self._native_admission_deadline) is float and math.isfinite(self._native_admission_deadline)),
                "invalid private native admission control")
        self.receive_state_lock = threading.Lock()
        self.first_receive_failure = None
        self.later_receive_failure = None
        self._check_native_admission()
        self.process = subprocess.Popen(argv, stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                        stderr=subprocess.DEVNULL, close_fds=True)
        self.reader = threading.Thread(target=self._read, daemon=True)
        self.reader.start()
        try:
            self.identity = self.request("initialize", {"protocolVersion": "2026-07-28", "capabilities": {},
                        "clientInfo": {"name": "observatory-evidence", "version": "1.0.0"}})
            require(self.identity["serverInfo"] == {"name": "brain", "version": "0.0"}
                    and self.identity["protocolVersion"] == "2025-11-25", "native identity drift")
            self.send("notifications/initialized", {})
            self.tools = self.request("tools/list", {})
            require(record_digest(self.tools) == TOOLS_SHA, "native tool schema drift")
        except BaseException as primary:
            primary.request_receipts = self.requests
            if getattr(self.witness, "_before_cleanup", None) is not None and self.last_request is not None:
                self.last_request["constructor_error_type"] = type(primary).__name__
            try:
                self.close()
            except BaseException as cleanup:
                primary.cleanup_error_type = type(cleanup).__name__
            raise

    def _check_native_admission(self, receipt=None):
        cutoff = self._native_admission_deadline
        if cutoff is None:
            return
        checked = time.monotonic()
        if receipt is not None:
            receipt["native_admission_control"] = {"cutoff_monotonic": cutoff,
                                                    "checked_monotonic": checked}
        if checked >= cutoff:
            if receipt is not None:
                receipt["sent"] = False  # Known pre-effect denial, not an attempted write.
                self._fail(receipt, "native_admission_closed")
            raise RuntimeError("native process admission closed")

    def _receive_state(self):
        # One locked snapshot prevents EOF/overflow from racing past an earlier
        # actual failure. Returned failure metadata is immutable after capture.
        with self.receive_state_lock:
            terminal = {"end_kind": self.reader_end_kind,
                        "overflow_kind": None, "overflow_wire_sha256": None,
                        "overflow_wire_bytes": None, "later_failure_kind": None,
                        "later_failure_wire_sha256": None, "later_failure_wire_bytes": None}
            if self.receive_failed is not None:
                terminal.update(overflow_kind=self.receive_failed["kind"],
                                overflow_wire_sha256=self.receive_failed.get("wire_sha256"),
                                overflow_wire_bytes=self.receive_failed.get("wire_bytes"))
            if self.later_receive_failure is not None:
                terminal.update(later_failure_kind=self.later_receive_failure["kind"],
                                later_failure_wire_sha256=self.later_receive_failure.get("wire_sha256"),
                                later_failure_wire_bytes=self.later_receive_failure.get("wire_bytes"))
            return self.first_receive_failure, terminal

    def _enqueue(self, frame):
        with self.receive_state_lock:
            # A valid native rejection is a response, but its early cause is
            # retained independently of the bounded delivery queue.
            cause = None
            if frame["kind"] != "response" or "error_body_sha256" in frame:
                cause = dict(frame)
                if "error_body_sha256" in frame and frame["kind"] == "response":
                    cause["kind"] = "rpc_error"
            if cause is not None:
                if self.first_receive_failure is None:
                    self.first_receive_failure = cause
                elif self.later_receive_failure is None:
                    self.later_receive_failure = cause
            if self.receive_failed is not None:
                return False
            try:
                self.pending.put_nowait(frame)
                return True
            except queue.Full:
                self.receive_failed = {"kind": "queue_overflow", "wire_sha256": frame.get("wire_sha256"),
                                       "wire_bytes": frame.get("wire_bytes"), "wire_complete": False,
                                       "overflowed_frame_kind": frame["kind"]}
                if self.first_receive_failure is None:
                    self.first_receive_failure = dict(self.receive_failed)
                return False

    def _check_receive_failure(self, receipt, *, include_end=False):
        first, terminal = self._receive_state()
        if first is not None:
            qualified = (first["kind"] == "rpc_error" and
                         getattr(self.witness, "_qualified_native_error_sha256", None) == first.get("error_body_sha256") and
                         safe_native_error(first["value"]["error"], self.redactions)["complete"] is True and
                         terminal["overflow_kind"] is None and terminal["later_failure_kind"] is None and
                         terminal["end_kind"] is None)
            if not qualified:
                self._receive_failure(receipt, first)
        if include_end and terminal["end_kind"] is not None:
            self._receive_failure(receipt, {"kind": terminal["end_kind"], "wire_complete": False})

    def _read(self):
        frame, reached_eof = None, False
        try:
            while True:
                line = self.process.stdout.readline(MAX_NATIVE_FRAME_BYTES + 1)
                if not line:
                    reached_eof = True
                    break
                frame = {"wire_sha256": hashlib.sha256(line).hexdigest(), "wire_bytes": len(line),
                         "wire_complete": False}
                if len(line) > MAX_NATIVE_FRAME_BYTES:
                    frame["kind"] = "frame_overflow"
                    self._enqueue(frame)
                    break
                if not line.endswith(b"\n"):
                    reached_eof = True
                    frame["kind"] = "partial_frame"
                    self._enqueue(frame)
                    break
                frame["wire_complete"] = True
                try:
                    value = _strict_json(line)
                except BaseException:
                    frame["kind"] = "decode_error"
                else:
                    try:
                        frame["frame_sha256"] = record_digest(value)
                    except BaseException:
                        frame["kind"] = "canonicalization_error"
                    else:
                        frame["value"] = value
                        # Classify transport-independent violations at capture, before overflow.
                        if type(value) is not dict:
                            frame["kind"] = "non_object_response"
                        elif type(value.get("id")) is not int:
                            frame["kind"] = "correlation_id_invalid"
                        elif value.get("jsonrpc") != "2.0" or set(value) not in (
                                {"jsonrpc", "id", "result"}, {"jsonrpc", "id", "error"}):
                            frame["kind"] = "protocol_frame_invalid"
                        elif "result" in value and type(value["result"]) is not dict:
                            frame["kind"] = "protocol_frame_invalid"
                        elif "error" in value:
                            error = value["error"]
                            if type(error) is not dict or type(error.get("code")) is not int or type(error.get("message")) is not str:
                                frame["kind"] = "protocol_frame_invalid"
                            else:
                                frame["kind"] = "response"
                                frame["error_body_sha256"] = record_digest(error)
                        else:
                            frame["kind"] = "response"
                if not self._enqueue(frame):
                    break
                frame = None
        except BaseException:
            failed = {"kind": "read_error", "wire_complete": False}
            if frame is not None:
                failed.update(wire_sha256=frame.get("wire_sha256"), wire_bytes=frame.get("wire_bytes"))
            self._enqueue(failed)
        finally:
            with self.receive_state_lock:
                self.reader_end_kind = "eof" if reached_eof else "reader_stopped"
                # End metadata is additive; it cannot replace the captured first
                # failure even when its queued copy is not consumed or overflows.
                if self.receive_failed is None:
                    try:
                        self.pending.put_nowait({"kind": self.reader_end_kind, "wire_complete": False})
                    except queue.Full:
                        pass

    def _receive_failure(self, receipt, frame):
        first, terminal = self._receive_state()
        if first is not None:
            frame = first
        receipt.update(response_wire_sha256=frame.get("wire_sha256"),
                       response_wire_bytes=frame.get("wire_bytes"),
                       response_wire_complete=frame.get("wire_complete", False),
                       response_frame_sha256=frame.get("frame_sha256"),
                       receive_first_failure_kind=frame["kind"], receive_terminal=terminal)
        if "error_body_sha256" in frame:
            receipt["canonical_error_body_sha256"] = frame["error_body_sha256"]
        if (frame["kind"] == "rpc_error" and receipt.get("sent") is True and
                type(receipt.get("request_id")) is int and
                receipt["request_id"] == self.sequence == frame["value"]["id"]):
            body = frame["value"]["error"]
            receipt.update(phase="jsonrpc_error", response_error_body_sha256=frame["error_body_sha256"],
                           safe_native_error=safe_native_error(body, self.redactions))
            self._observe(receipt)
            error = NativeError(body)
            error.receipt = receipt
            raise error
        self._fail(receipt, frame["kind"])

    def _observe(self, receipt):
        if self.witness is not None:
            try:
                self.witness(dict(receipt))
            except BaseException:
                receipt["witness_failed"] = True
                hold = getattr(self.witness, "_hold_unretained", None)
                if hold is not None:
                    hold("witness_unavailable")
                raise NativeTransportError("witness_unavailable", receipt) from None

    def _fail(self, receipt, phase):
        with self.receive_state_lock:
            if self.first_receive_failure is None:
                self.first_receive_failure = {"kind": phase,
                    "wire_sha256": receipt.get("response_wire_sha256"),
                    "wire_bytes": receipt.get("response_wire_bytes"),
                    "wire_complete": receipt.get("response_wire_complete", False),
                    "frame_sha256": receipt.get("response_frame_sha256")}
        first, terminal = self._receive_state()
        receipt.update(phase=first["kind"], response_wire_sha256=first.get("wire_sha256"),
                       response_wire_bytes=first.get("wire_bytes"),
                       response_wire_complete=first.get("wire_complete", False),
                       response_frame_sha256=first.get("frame_sha256"),
                       receive_first_failure_kind=first["kind"], receive_terminal=terminal)
        self._observe(receipt)
        raise NativeTransportError(first["kind"], receipt)

    def send(self, method, params, ident=None):
        require(method in {"initialize", "tools/list", "tools/call", "notifications/initialized"}, "unadmitted RPC method")
        if method == "tools/call":
            require(isinstance(params, dict) and params.get("name") in {"brain_get", "brain_remember"} and isinstance(params.get("arguments"), dict), "unadmitted native request frame")
        receipt = {"method": method, "request_id": ident, "parameters_sha256": None,
                   "request_wire_sha256": None, "request_wire_bytes": None, "sent": None, "phase": "attempted",
                   "response_wire_sha256": None, "response_frame_sha256": None,
                   "response_result_sha256": None, "response_error_body_sha256": None}
        if method == "tools/call":
            receipt.update(tool=params["name"], arguments_sha256=None)
            self.calls.append(receipt)
        self.requests.append(receipt)
        self.last_request = receipt
        self._observe(receipt)
        self._check_receive_failure(receipt, include_end=True)
        try:
            message = {"jsonrpc": "2.0", "method": method, "params": params}
            if ident is not None:
                message["id"] = ident
            payload = (canonical(message) + "\n").encode()
            receipt.update(parameters_sha256=record_digest(params), request_wire_sha256=hashlib.sha256(payload).hexdigest(), request_wire_bytes=len(payload))
            if method == "tools/call":
                receipt["arguments_sha256"] = record_digest(params["arguments"])
        except (TypeError, ValueError, UnicodeError, RecursionError, OverflowError):
            self._fail(receipt, "request_encode_error")
        self._observe(receipt)
        # This independent check occurs AFTER any backpressured observer write,
        # immediately before the native effect; queued intent is not admission.
        self._check_receive_failure(receipt, include_end=True)
        self._check_native_admission(receipt)
        try:
            written = self.process.stdin.write(payload)
            self.process.stdin.flush()
            if written != len(payload):
                self._fail(receipt, "send_partial")
        except (OSError, ValueError):
            self._fail(receipt, "send_error")
        receipt["sent"] = True
        receipt["phase"] = "sent" if ident is not None else "notification_sent"
        self._observe(receipt)
        return receipt

    def request(self, method, params):
        self.sequence += 1
        receipt = self.send(method, params, self.sequence)
        due = time.monotonic() + 30
        unmatched = 0
        while True:
            self._check_receive_failure(receipt)
            try:
                frame = self.pending.get(timeout=max(0.001, due - time.monotonic()))
            except queue.Empty:
                self._check_receive_failure(receipt, include_end=True)
                self._fail(receipt, "response_timeout")
            self._check_receive_failure(receipt)
            if frame["kind"] != "response":
                self._receive_failure(receipt, frame)
            response = frame["value"]
            if not isinstance(response, dict):
                receipt.update(response_wire_sha256=frame["wire_sha256"], response_wire_bytes=frame["wire_bytes"],
                               response_frame_sha256=frame["frame_sha256"], response_wire_complete=True)
                self._fail(receipt, "non_object_response")
            if type(response.get("id")) is not int:
                receipt.update(response_wire_sha256=frame["wire_sha256"], response_wire_bytes=frame["wire_bytes"],
                               response_frame_sha256=frame["frame_sha256"], response_wire_complete=True)
                self._fail(receipt, "correlation_id_invalid")
            if response.get("id") != self.sequence:
                unmatched += 1
                receipt.update(unmatched_count=unmatched, last_unmatched_wire_sha256=frame["wire_sha256"])
                self._observe(receipt)
                if unmatched >= 8 or time.monotonic() >= due:
                    self._fail(receipt, "correlation_failure")
                continue
            receipt.update(response_wire_sha256=frame["wire_sha256"], response_wire_bytes=frame["wire_bytes"],
                           response_frame_sha256=frame["frame_sha256"], response_wire_complete=True)
            if response.get("jsonrpc") != "2.0" or set(response) not in ({"jsonrpc", "id", "result"}, {"jsonrpc", "id", "error"}):
                self._fail(receipt, "protocol_frame_invalid")
            if "error" in response:
                self._receive_failure(receipt, {**frame, "kind": "rpc_error",
                                               "error_body_sha256": record_digest(response["error"])})
            if "result" not in response:
                self._fail(receipt, "result_missing")
            receipt.update(phase="result_received", response_result_sha256=record_digest(response["result"]))
            self._observe(receipt)
            return response["result"]

    def call(self, name, arguments):
        require(arguments.get("brain_id") == self.brain_id, "foreign or implicit authority")
        require(name in {"brain_remember", "brain_get"}, "unadmitted native operation")
        schema = next(t["inputSchema"] for t in self.tools["tools"] if t["name"] == name)
        require(set(arguments) <= set(schema["properties"]) and set(schema.get("required", [])) <= set(arguments), "native arguments drift")
        wire = self.request("tools/call", {"name": name, "arguments": arguments})
        receipt = self.last_request
        if not isinstance(wire, dict):
            self._fail(receipt, "tool_result_invalid")
        if "isError" in wire and type(wire["isError"]) is not bool:
            self._fail(receipt, "tool_result_invalid")
        if wire.get("isError") is True:
            receipt.update(phase="tool_error", response_error_body_sha256=record_digest(wire),
                           safe_native_error=safe_native_error(wire, self.redactions))
            self._observe(receipt)
            error = NativeError(wire)
            error.receipt = receipt
            raise error
        if not set(wire) <= {"content", "structuredContent", "isError"}:
            self._fail(receipt, "tool_result_incomplete")
        if not {"content", "structuredContent"} & set(wire):
            self._fail(receipt, "tool_result_incomplete")
        result = wire.get("structuredContent")
        if "structuredContent" in wire and type(result) is not dict:
            self._fail(receipt, "tool_result_incomplete")
        if "content" in wire:
            content = wire["content"]
